class BatchProcessor(_BatchCore):
    """Batches records for a synchronous :class:`LogExporter` on a daemon worker thread.

    The worker starts with the first record. It exports when a batch is full, when
    ``flush_interval_s`` passed since the first queued record, on :meth:`flush` and on
    :meth:`shutdown`. Processors with a started worker are shut down at interpreter exit.
    """

    def __init__(self, exporter: LogExporter, options: BatchOptions | None = None) -> None:
        super().__init__(options)
        self._exporter = exporter
        self._thread: threading.Thread | None = None
        self._shutdown_lock = threading.Lock()
        self._shutdown_done = False

    def add(self, record: LogRecord) -> bool:
        """Queue a record; False when it was dropped. Blocks only with ``drop_policy="block"``."""
        size = record.json_size()
        reason: DropReason = "queue_full"
        with self._cond:
            if self.options.drop_policy == "block":
                while not self._closed and not self._has_space_locked():
                    self._cond.wait()
            if self._closed:
                accepted, wake, dropped = False, False, self._reject_closed_locked(record)
                reason = "shutdown"
            else:
                accepted, wake, dropped = self._offer_locked(record, size)
            if accepted:
                self._ensure_worker_locked()
                if wake:
                    self._cond.notify_all()
        self._notify_drop(dropped, reason)
        return accepted

    def flush(self, timeout_s: float | timedelta | None = None) -> None:
        """Export everything queued now; raises ``TimeoutError`` when ``timeout_s`` passes first."""
        deadline = None if timeout_s is None else time.monotonic() + to_seconds(timeout_s)
        with self._cond:
            target = self._accepted_total
            if self._completed_total >= target or threading.current_thread() is self._thread:
                return
            self._flush_target = max(self._flush_target, target)
            self._ensure_worker_locked()
            self._cond.notify_all()
            while self._completed_total < target:
                remaining = None if deadline is None else deadline - time.monotonic()
                if remaining is not None and remaining <= 0:
                    raise _errors.TimeoutError("logs.flush: timed out")
                self._cond.wait(remaining)

    def shutdown(self, timeout_s: float | timedelta | None = None) -> None:
        """Drain the queue (bounded by ``timeout_s``), stop the worker and shut the exporter down.

        Idempotent. Records still queued when the timeout passes are dropped with reason
        ``shutdown``; later :meth:`add` calls are dropped the same way.
        """
        with self._shutdown_lock:
            if self._shutdown_done:
                return
            self._shutdown_done = True
            deadline = None if timeout_s is None else time.monotonic() + to_seconds(timeout_s)
            with self._cond:
                self._closed = True
                self._cond.notify_all()
            with contextlib.suppress(_errors.TimeoutError):
                self.flush(timeout_s)
            with self._cond:
                leftover = self._drain_closed_locked()
                thread = self._thread
            self._notify_drop(leftover, "shutdown")
            if thread is not None and thread is not threading.current_thread():
                thread.join(None if deadline is None else max(0.0, deadline - time.monotonic()))
            try:
                self._exporter.shutdown()
            except Exception as exc:  # noqa: BLE001 - reported, never raised
                self._notify_error(exc, [])

    def _ensure_worker_locked(self) -> None:
        if self._thread is None:
            self._thread = threading.Thread(
                target=self._run,
                name=f"{WORKER_THREAD_PREFIX}-batch",
                daemon=True,
            )
            self._thread.start()
            atexit.register(_atexit_shutdown, weakref.ref(self))

    def _run(self) -> None:
        while True:
            with self._cond:
                action, timeout = self._next_action_locked()
                while action == "wait":
                    self._cond.wait(timeout)
                    action, timeout = self._next_action_locked()
                if action == "exit":
                    return
                batch = self._take_batch_locked()
                self._cond.notify_all()
            self._export(batch)

    def _export(self, batch: list[LogRecord]) -> None:
        attempt = 0
        while True:
            result: ExportResult | None = None
            error: Exception | None = None
            try:
                result = self._exporter.export(
                    batch, gzip=self.options.gzip, timeout_s=self.options.export_timeout_s
                )
            except Exception as exc:  # noqa: BLE001 - exporter failures become stats + callbacks
                error = exc
            delay = self._retry_delay(result, error, attempt)
            if delay is None:
                break
            time.sleep(delay)
            attempt += 1
        with self._cond:
            dropped, reported = self._finish_locked(batch, result, error)
            self._cond.notify_all()
        self._report(dropped, reported, batch)


class AsyncBatchProcessor(_BatchCore):
    """Batches records for an :class:`AsyncLogExporter` on an asyncio task.

    The task starts on the running loop at the first :meth:`add` (or :meth:`flush`). :meth:`add`
    may be called from other threads; it wakes the worker thread-safely. Exports are bounded by
    ``export_timeout_s`` with :func:`asyncio.wait_for`.
    """

    def __init__(self, exporter: AsyncLogExporter, options: BatchOptions | None = None) -> None:
        super().__init__(options)
        self._exporter = exporter
        self._loop: asyncio.AbstractEventLoop | None = None
        self._task: asyncio.Task[None] | None = None
        self._wake: asyncio.Event | None = None
        self._progress: asyncio.Event | None = None
        self._shutdown_task: asyncio.Future[None] | None = None

    def add(self, record: LogRecord) -> bool:
        """Queue without blocking; False when dropped (``block`` acts as ``drop_newest`` here)."""
        size = record.json_size()
        reason: DropReason = "queue_full"
        with self._cond:
            if self._closed:
                accepted, wake, dropped = False, False, self._reject_closed_locked(record)
                reason = "shutdown"
            else:
                accepted, wake, dropped = self._offer_locked(record, size)
        if wake:
            self._wake_worker()
        self._notify_drop(dropped, reason)
        return accepted

    async def add_wait(self, record: LogRecord) -> bool:
        """Queue a record, waiting for queue space with ``drop_policy="block"``."""
        if self.options.drop_policy != "block":
            return self.add(record)
        size = record.json_size()
        while True:
            self._ensure_worker()
            assert self._progress is not None
            progress = self._progress
            with self._cond:
                if self._closed:
                    dropped = self._reject_closed_locked(record)
                    break
                if self._has_space_locked():
                    wake = self._push_locked(record, size)
                    dropped = []
                    break
            await progress.wait()
        if dropped:
            self._notify_drop(dropped, "shutdown")
            return False
        if wake:
            self._wake_worker()
        return True

    async def flush(self, timeout_s: float | timedelta | None = None) -> None:
        """Export everything queued now; raises ``TimeoutError`` when ``timeout_s`` passes first."""
        with self._cond:
            target = self._accepted_total
            if self._completed_total >= target:
                return
            self._flush_target = max(self._flush_target, target)
        self._ensure_worker()
        self._wake_worker()
        try:
            await asyncio.wait_for(
                self._wait_completed(target), None if timeout_s is None else to_seconds(timeout_s)
            )
        except asyncio.TimeoutError:
            raise _errors.TimeoutError("logs.flush: timed out") from None

