        """Drain (bounded by ``timeout_s``), stop the task, shut the exporter down; idempotent."""
        if self._shutdown_task is None:
            self._shutdown_task = asyncio.ensure_future(self._shutdown(timeout_s))
        await asyncio.shield(self._shutdown_task)

